<?php
require_once dirname(__DIR__,2).'/app/bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'');if($id>0&&in_array($status,['published','rejected'],true)){db()->prepare('UPDATE community_posts SET status=:s,updated_at=CURRENT_TIMESTAMP WHERE id=:i')->execute([':s'=>$status,':i'=>$id]);if($status==='published'){$s=db()->prepare('SELECT user_id FROM community_posts WHERE id=:i');$s->execute([':i'=>$id]);if($u=$s->fetchColumn())notify_user((int)$u,'Your community post is live','Your post has been approved and is now visible in the LocalGuide community feed.','community-feed.php');}flash('success','Community post updated.');}redirect(app_path('admin/social.php'));}$posts=db()->query("SELECT p.*,u.name,u.username,l.name listing_name FROM community_posts p JOIN users u ON u.id=p.user_id LEFT JOIN listings l ON l.id=p.listing_id WHERE p.status='pending' ORDER BY p.created_at ASC LIMIT 150")->fetchAll();$adminTitle='Community moderation';include __DIR__.'/_header.php';?>
<section class="content-panel"><div class="panel-heading"><div><span class="eyebrow">VERSION 4 COMMUNITY</span><h2>Pending posts</h2></div><span class="status-pill status-pending"><?= count($posts) ?> awaiting review</span></div><?php if($posts): ?><div class="admin-list"><?php foreach($posts as $post): ?><article class="admin-row"><div><strong><?= h($post['name']) ?> <small>@<?= h($post['username']) ?></small></strong><p><?= nl2br(h($post['body'])) ?></p><?php if($post['listing_name']): ?><small>Related place: <?= h($post['listing_name']) ?></small><?php endif; ?><small>Submitted <?= h(format_date($post['created_at'])) ?></small></div><div class="admin-row-actions"><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$post['id'] ?>"><input type="hidden" name="status" value="published"><button class="button button-primary button-small">Approve</button></form><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$post['id'] ?>"><input type="hidden" name="status" value="rejected"><button class="button button-outline button-small">Reject</button></form></div></article><?php endforeach; ?></div><?php else: ?><div class="empty-state"><h3>No posts awaiting review.</h3></div><?php endif; ?></section><?php include __DIR__.'/_footer.php';?>
